#include <string.h>

int main() {
    char str[100]; // Your coffee beans, the buffer for the input string
    printf("Enter a string: ");
    fgets(str, sizeof(str), stdin); // Blooming the beans: reading input safely

    // Remove newline character if present
    size_t len = strlen(str);
